import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"LocalSend 設定","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 基本サービス設定","slug":"_1-基本サービス設定","link":"#_1-基本サービス設定","children":[]},{"level":2,"title":"2. セキュリティ・暗号化・保存先","slug":"_2-セキュリティ・暗号化・保存先","link":"#_2-セキュリティ・暗号化・保存先","children":[]},{"level":2,"title":"3. 送信画面と操作方法","slug":"_3-送信画面と操作方法","link":"#_3-送信画面と操作方法","children":[]}],"relativePath":"ja-JP/user-guide/settings/localsend.md","filePath":"ja-JP/user-guide/settings/localsend.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/settings/localsend.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="localsend-設定" tabindex="-1">LocalSend 設定 <a class="header-anchor" href="#localsend-設定" aria-label="Permalink to “LocalSend 設定”">​</a></h1><p>Lertaro は、オープンソースの <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> プロトコルとネイティブ互換性を持つ LAN 内ファイル転送エンジンを内蔵しています。外部のインターネットやケーブルを必要とせず、同一 LAN 内にある Windows、Mac、Linux、iPhone、iPad、Android デバイス間でファイル、フォルダー、テキストを送受信できます。設定画面は <strong>設定 → LocalSend</strong> です。</p><h2 id="_1-基本サービス設定" tabindex="-1">1. 基本サービス設定 <a class="header-anchor" href="#_1-基本サービス設定" aria-label="Permalink to “1. 基本サービス設定”">​</a></h2><ul><li><strong>LocalSend 転送サービスを有効化</strong>：全体のスイッチ。有効にするとバックグラウンドで待受サービスが起動し、トレイメニューに「他のデバイスへ送信...」項目が追加されます。</li><li><strong>デバイス名</strong>：LAN 内の他デバイスに表示される名前。初期設定ではコンピューター名が使用されますが、自由に変更可能です（例: <code>作業用ノートPC</code>）。</li><li><strong>サービスポート</strong>：HTTP / HTTPS 待受ポート（LocalSend 標準の <code>53317</code> が既定）。競合がある場合は変更できます。</li></ul><h2 id="_2-セキュリティ・暗号化・保存先" tabindex="-1">2. セキュリティ・暗号化・保存先 <a class="header-anchor" href="#_2-セキュリティ・暗号化・保存先" aria-label="Permalink to “2. セキュリティ・暗号化・保存先”">​</a></h2><ul><li><strong>暗号化転送 (HTTPS)</strong>：既定で有効。デバイス間の通信を TLS で暗号化し、LAN 内の盗聴を防ぎます。</li><li><strong>受信 PIN コード</strong>：PIN を設定できます（空欄で無効）。設定時は、送信側で一致する PIN の入力が必要になります。</li><li><strong>ファイルの自動保存</strong>：有効にすると、信頼できるクライアントからの転送要求を手動の確認なしで自動承認・保存します。</li><li><strong>保存先ディレクトリ</strong>：受信したファイルの保存先（既定はシステムの「ダウンロード」フォルダー）。参照ボタンから変更可能です。</li></ul><h2 id="_3-送信画面と操作方法" tabindex="-1">3. 送信画面と操作方法 <a class="header-anchor" href="#_3-送信画面と操作方法" aria-label="Permalink to “3. 送信画面と操作方法”">​</a></h2><ul><li><strong>ホットキーによる起動</strong>：グローバルホットキー <strong><code>Ctrl+S</code></strong>（<a href="./hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で変更可能）で送信画面を呼び出せます。</li><li><strong>送信モードの切り替え</strong>：送信画面上部で <strong>[ファイル / フォルダー送信]</strong> と <strong>[テキスト送信]</strong> を切り替え可能。</li><li><strong>ドラッグ＆ドロップでのファイル追加</strong>：Lertaro の検索結果、クイックパネル、エクスプローラーからファイルを送信ウィンドウへ直接ドラッグして追加可能。レーダーで検出されたデバイスをクリックするだけで高速転送されます。</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};